const items = $input.all();
const result = [];

function formatCustomDate(dateStr) {
  if (!dateStr) return "";
  const d = new Date(dateStr);
  const months = ["Jan", "Feb", "Mar", "Apr", "May", "Jun", "Jul", "Aug", "Sep", "Oct", "Nov", "Dec"];
  const day = d.getDate();
  const month = months[d.getMonth()];
  const year = d.getFullYear();
  let hours = d.getHours();
  let minutes = d.getMinutes();
  const ampm = hours >= 12 ? 'pm' : 'am';
  hours = hours % 12;
  hours = hours ? hours : 12; 
  const paddedHours = hours < 10 ? '0' + hours : hours;
  const paddedMinutes = minutes < 10 ? '0' + minutes : minutes;
  return `${day} ${month} ${year}, ${paddedHours}:${paddedMinutes} ${ampm}`;
}

for (const item of items) {
  const data = item.json;
  let shipmentDataList = [];

  // Identify where ShipmentData lives
  if (data.ShipmentData) {
    shipmentDataList = data.ShipmentData;
  } else if (Array.isArray(data) && data[0] && data[0].ShipmentData) {
    shipmentDataList = data[0].ShipmentData;
  } else {
    shipmentDataList = data;
  }

  for (const shipmentWrapper of shipmentDataList) {
    const shipment = shipmentWrapper.Shipment;
    if (!shipment) continue;

    let journeyText = "";
    if (shipment.Scans && shipment.Scans.length > 0) {
      for (const scanObj of shipment.Scans) {
        const scan = scanObj.ScanDetail;
        const formattedDate = formatCustomDate(scan.ScanDateTime);
        journeyText += `${formattedDate}\n${scan.Instructions} at ${scan.ScannedLocation}\n\n`;
      }
    } else {
      journeyText = "No journey scans available.";
    }

    result.push({
      json: {
        "AWB": shipment.AWB || "",
        "Status": shipment.Status?.Status || "",
        "Status Details": shipment.Status?.Instructions || "",
        "Consignee": shipment.Consignee?.Name || "",
        "Delivery Date": shipment.DeliveryDate ? formatCustomDate(shipment.DeliveryDate) : "Pending",
        "Journey": journeyText.trim()
      }
    });
  }
}
return result;
